import {useEffect } from 'react';
import axios from 'axios';


export default function KpWidget(){


    async function fetchKp(){
        try{
            const response = await axios.get(`https://services.swpc.noaa.gov/text/3-day-geomag-forecast.txt`);
            console.log(response.data.slice(510));
            const sliced_response = response.data.slice(510);
            const k_indexs=[];
            while(sliced_response!=""){
                k_indexs.push(sliced_response.slice(14,16));
                sliced_response=sliced_response.slice(40);
            }
        }

        catch(error){
            console.error(error);
        }
    }


    useEffect(()=>{
        fetchKp();
    }, [])
}
